def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0:
                candidates = [
                    grid[i][w - 1 - j],
                    grid[h - 1 - i][j],
                    grid[h - 1 - i][w - 1 - j],
                ]
                out[i][j] = next((v for v in candidates if v != 0), 0)
    return out
