def transform(grid):
    rows = [i for i, row in enumerate(grid) if 0 in row]
    cols = [j for j in range(len(grid[0])) if any(grid[i][j] == 0 for i in range(len(grid)))]
    r0, r1 = min(rows), max(rows)
    c0, c1 = min(cols), max(cols)
    return [
        [grid[len(grid) - 1 - i][j] if grid[i][j] == 0 else grid[i][j]
         for j in range(c0, c1 + 1)]
        for i in range(r0, r1 + 1)
    ]
